<?phpnamespace app\api\service\business;use app\api\service\CommService;use app\common\model\business\MallServiceType;class ServiceTypeService extends CommService{    public function __construct($param, $user_info)    {        parent::_initialize($param, $user_info);    }    public function getServiceTypeList()    {        $this->data['service_type_list'] = MallServiceType::where('status', 1)->field('type_id,name')->order('sort', 'desc')->select();        return $this->data;    }}